/**
 * The evidence ledger: one row per numeric constant of the model, with the
 * provenance tag and the `EV-xx` ids its own `fuente` cites
 * (docs/EVIDENCIA.md). Generated by `node scripts/evidence/ledger.mjs --write`;
 * `src/config/evidence-ledger.test.ts` fails when a parameter moves without the
 * ledger being regenerated, which is the mechanical half of "cada parámetro se
 * vincula a su origen".
 *
 * Only the two annotated configuration files are indexed leaf by leaf. The
 * psychometric parameters are estimated by `scripts/psychometrics/run.py` over a
 * synthetic population, so they enter as a file stamp (seed, N, input hash):
 * their provenance is reproducible regeneration, not a hand-written row.
 */
import { PARAM_LABELS, type ParamLabel } from "@/types/matching-config";

export const LEDGER_VERSION = "evidence-ledger-1";

export interface IndexedFile {
  readonly archivo: string;
  readonly rol: string;
}

/** Files walked number by number, in report order. */
export const INDEXED_FILES: readonly IndexedFile[] = [
  { archivo: "data/matching-config.json", rol: "modelo por capas: pesos, ventanas, umbrales y top-K" },
  { archivo: "data/rollout-gates.json", rol: "compuertas de activación del motor" },
];

/** Estimated parameters: stamped, not walked. */
export const STAMPED_FILES: readonly IndexedFile[] = [
  { archivo: "data/psychometric-params.json", rol: "parámetros GRM/ω estimados sobre datos sintéticos" },
];

export interface LedgerEntry {
  readonly id: string;
  readonly archivo: string;
  readonly ruta: string;
  readonly valor: number;
  readonly etiqueta: ParamLabel;
  readonly fuente: string;
  readonly ev: readonly string[];
}

export interface EvidenceLedger {
  readonly version: typeof LEDGER_VERSION;
  readonly nota: string;
  readonly etiquetas: readonly ParamLabel[];
  readonly archivos: Record<string, { readonly rol: string; readonly entradas: number }>;
  readonly sello: Record<string, unknown>;
  readonly entradas: readonly LedgerEntry[];
  readonly resumen: {
    readonly total: number;
    readonly porEtiqueta: Record<string, number>;
    readonly conEv: number;
    readonly sinEv: number;
  };
}

const META_KEYS = new Set(["valor", "etiqueta", "fuente"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function citedEvidence(fuente: string): string[] {
  return [...new Set(fuente.match(/EV-\d+/g) ?? [])].sort((a, b) => Number(a.slice(3)) - Number(b.slice(3)));
}

/**
 * Walks one configuration document and emits a row for every number, inheriting
 * the nearest `{etiqueta, fuente}` pair above it. A `{valor, etiqueta, fuente}`
 * object is one row at its own path: its payload is never walked again.
 */
export function collectEntries(archivo: string, source: unknown): LedgerEntry[] {
  const rows: Array<Omit<LedgerEntry, "id">> = [];

  const walk = (node: unknown, path: string, tag: ParamLabel | null, fuente: string): void => {
    if (typeof node === "number") {
      if (!Number.isFinite(node)) throw new Error(`${archivo}${path}: número no finito`);
      if (!tag || !fuente) throw new Error(`${archivo}${path}: número sin etiqueta ni fuente de procedencia`);
      rows.push({ archivo, ruta: path.slice(1), valor: node, etiqueta: tag, fuente, ev: citedEvidence(fuente) });
      return;
    }
    if (!isRecord(node)) return;

    const rawValor = node.valor;
    const rawEtiqueta = node.etiqueta;
    const rawFuente = node.fuente;
    if (typeof rawValor === "number" && typeof rawEtiqueta === "string" && typeof rawFuente === "string") {
      rows.push({
        archivo,
        ruta: path.slice(1),
        valor: rawValor,
        etiqueta: rawEtiqueta as ParamLabel,
        fuente: rawFuente,
        ev: citedEvidence(rawFuente),
      });
      return;
    }

    const nextTag = typeof node.etiqueta === "string" ? (node.etiqueta as ParamLabel) : tag;
    const nextFuente = typeof node.fuente === "string" && node.fuente.length > 0 ? node.fuente : fuente;
    for (const [key, value] of Object.entries(node)) {
      if (META_KEYS.has(key)) continue;
      if (Array.isArray(value)) {
        value.forEach((item, index) => walk(item, `${path}.${key}[${index}]`, nextTag, nextFuente));
      } else {
        walk(value, `${path}.${key}`, nextTag, nextFuente);
      }
    }
  };

  for (const [key, value] of Object.entries(isRecord(source) ? source : {})) {
    if (META_KEYS.has(key)) continue;
    if (Array.isArray(value)) {
      value.forEach((item, index) => walk(item, `.${key}[${index}]`, null, ""));
    } else {
      walk(value, `.${key}`, null, "");
    }
  }

  rows.sort((a, b) => (a.ruta < b.ruta ? -1 : a.ruta > b.ruta ? 1 : 0));
  return rows.map((row, index) => ({ ...row, id: `E-${String(index + 1).padStart(3, "0")}` }));
}

function stampOf(source: unknown): Record<string, unknown> {
  const file = isRecord(source) ? source : {};
  const labels = new Map<string, number>();
  const count = (node: unknown): void => {
    if (Array.isArray(node)) {
      for (const value of node) count(value);
      return;
    }
    if (!isRecord(node)) return;
    const etiqueta = node.etiqueta;
    if (typeof etiqueta === "string") labels.set(etiqueta, (labels.get(etiqueta) ?? 0) + 1);
    for (const value of Object.values(node)) count(value);
  };
  count(file);
  return {
    version: file.version,
    generado_por: file.generado_por,
    semilla: file.semilla,
    n_sintetico: file.n_sintetico,
    entrada_sha256: file.entrada_sha256,
    advertencia: file.advertencia,
    etiquetas_internas: Object.fromEntries([...labels.entries()].sort()),
  };
}

export function buildLedger(sources: Record<string, unknown>): EvidenceLedger {
  const entradas = INDEXED_FILES.flatMap(({ archivo }) =>
    archivo in sources ? collectEntries(archivo, sources[archivo]) : [],
  ).map((entry, index) => ({ ...entry, id: `E-${String(index + 1).padStart(3, "0")}` }));

  const archivos: EvidenceLedger["archivos"] = {};
  for (const { archivo, rol } of INDEXED_FILES) {
    archivos[archivo] = { rol, entradas: entradas.filter((e) => e.archivo === archivo).length };
  }

  const porEtiqueta: Record<string, number> = {};
  for (const label of PARAM_LABELS) porEtiqueta[label] = 0;
  for (const entry of entradas) porEtiqueta[entry.etiqueta] = (porEtiqueta[entry.etiqueta] ?? 0) + 1;

  const sello: Record<string, unknown> = {};
  for (const { archivo, rol } of STAMPED_FILES) {
    if (archivo in sources) sello[archivo] = { rol, ...stampOf(sources[archivo]) };
  }

  return {
    version: LEDGER_VERSION,
    nota:
      "Registro de procedencia generado por scripts/evidence/ledger.mjs --write. Una fila por cada número de " +
      "data/matching-config.json y data/rollout-gates.json, con la etiqueta y la fuente que el propio archivo " +
      "declara y los EV-xx que esa fuente cita (docs/EVIDENCIA.md). No se edita a mano: si cambia un parámetro " +
      "sin regenerar este archivo, src/config/evidence-ledger.test.ts falla. Los ítems y parámetros de " +
      "data/psychometric-params.json no llevan fila: son estimaciones reproducibles y entran en `sello` con su " +
      "semilla, N y hash de entradas.",
    etiquetas: PARAM_LABELS,
    archivos,
    sello,
    entradas,
    resumen: {
      total: entradas.length,
      porEtiqueta,
      conEv: entradas.filter((e) => e.ev.length > 0).length,
      sinEv: entradas.filter((e) => e.ev.length === 0).length,
    },
  };
}

export function serializeLedger(ledger: EvidenceLedger): string {
  return `${JSON.stringify(ledger, null, 2)}\n`;
}
